<!doctype html>
<html lang="{{ $user->preferred_locale ?? 'en' }}">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <meta name="csrf-token" content="{{ csrf_token() }}">
    <title>Tax Rates &amp; Groups · {{ $workspace->name }}</title>
    <style>
        :root{--navy:#12223a;--navy2:#1a2e49;--blue:#2f7be5;--ink:#263548;--muted:#77869a;--line:#e3e9f0;--bg:#f4f7fb;--white:#fff;--green:#15865d;--red:#c34e4e;--amber:#a46b12;--shadow:0 14px 40px rgba(20,42,69,.10)}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif;font-size:14px}.topbar{height:62px;background:var(--navy);display:flex;align-items:center;padding:0 25px;gap:22px;color:#fff}.brand{font-weight:800;font-size:17px;letter-spacing:-.4px;white-space:nowrap}.brand span{color:#76b9ff}.topnav{display:flex;align-items:center;gap:8px;flex:1}.topnav a{color:#c9d4e3;text-decoration:none;font-size:12px;padding:9px 11px;border-radius:7px}.topnav a.active,.topnav a:hover{background:#ffffff18;color:#fff}.biz{font-size:11px;color:#d5deea;white-space:nowrap}.user{font-size:11px;color:#cbd6e5;white-space:nowrap}.logout{border:1px solid #53647b;background:transparent;color:#fff;border-radius:7px;padding:8px 10px;font-weight:700;font-size:10px;cursor:pointer}.wrap{max-width:1440px;margin:0 auto;padding:28px 28px 48px}.eyebrow{font-size:10px;letter-spacing:1.2px;text-transform:uppercase;color:#8b9ab0;font-weight:800;margin-bottom:8px}.head{display:flex;justify-content:space-between;align-items:flex-start;gap:16px;margin-bottom:18px}.head h1{font-size:25px;letter-spacing:-.8px;margin:0;color:#1d2e43}.head p{font-size:12px;color:var(--muted);margin:7px 0 0;line-height:1.55;max-width:720px}.actions{display:flex;gap:8px;flex-wrap:wrap}.btn{border:1px solid var(--line);background:#fff;border-radius:8px;padding:9px 12px;color:#526276;font-size:11px;font-weight:750;cursor:pointer;transition:.15s}.btn:hover{box-shadow:0 4px 14px #243d5b12;transform:translateY(-1px)}.btn.primary{background:var(--blue);border-color:var(--blue);color:#fff}.btn.small{padding:6px 8px;font-size:10px}.btn.danger{color:var(--red)}.notice{border:1px solid #f0dfb8;background:#fff8e9;color:#80662f;padding:12px 14px;border-radius:9px;font-size:11px;line-height:1.55;margin:0 0 15px}.notice strong{color:#70551d}.alert{display:none;border-radius:8px;padding:10px 12px;font-size:11px;margin-bottom:12px}.alert.show{display:block}.alert.error{background:#fff1f0;color:#a83f3f;border:1px solid #f0d2d0}.alert.success{background:#edfaf3;color:#16764f;border:1px solid #ccead9}.card{background:var(--white);border:1px solid var(--line);border-radius:12px;box-shadow:0 2px 5px rgba(22,42,68,.025);overflow:hidden}.tabs{display:flex;gap:4px;padding:11px 14px;border-bottom:1px solid var(--line);overflow:auto}.tab{border:0;background:transparent;padding:10px 13px;color:#68788c;font-weight:750;font-size:11px;border-radius:7px;white-space:nowrap;cursor:pointer}.tab.active{background:#eaf3ff;color:#236bc4}.body{padding:16px}.subhead{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:13px}.subhead h2{margin:0;font-size:13px}.subhead p{margin:4px 0 0;color:var(--muted);font-size:10px}.table-wrap{overflow:auto;border:1px solid #e9edf3;border-radius:8px}table{width:100%;border-collapse:collapse;min-width:790px}th{background:#f7f9fc;color:#7b899b;text-align:left;padding:10px 12px;font-size:9px;text-transform:uppercase;letter-spacing:.5px;border-bottom:1px solid var(--line);white-space:nowrap}td{padding:11px 12px;border-bottom:1px solid #edf0f4;font-size:11px;color:#48596d;vertical-align:middle}tr:last-child td{border-bottom:0}.code{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:10px;font-weight:800;color:#286bc5}.status{font-size:9px;font-weight:800;padding:4px 7px;border-radius:99px;background:#e8f7ef;color:#188458}.status.off{background:#f0f2f5;color:#7a8794}.rate-stack{display:flex;flex-wrap:wrap;gap:5px}.rate-chip{font-size:9px;padding:4px 6px;border-radius:6px;background:#f0f4fa;color:#5d6d81}.muted{color:#8b98a8}.tools{display:flex;gap:6px;align-items:center;white-space:nowrap}.empty{padding:32px;text-align:center;color:#8290a0;font-size:11px}.calc-grid{display:grid;grid-template-columns:1.05fr .95fr;gap:18px}.calc-box{border:1px solid var(--line);border-radius:10px;padding:16px}.calc-box h2{font-size:14px;margin:0 0 6px}.calc-box p{font-size:10px;color:var(--muted);margin:0 0 14px;line-height:1.55}.fields{display:grid;grid-template-columns:1fr 1fr;gap:12px}.field label{display:block;color:#6b7a8d;font-size:10px;font-weight:750;margin-bottom:5px}.input,.select,.textarea{width:100%;border:1px solid #dce3ec;background:#fff;border-radius:7px;padding:9px 10px;color:#33465c;font-size:11px;outline:none}.input:focus,.select:focus,.textarea:focus{border-color:#80b2f3;box-shadow:0 0 0 3px #2f7be51a}.checkrow{display:flex;align-items:center;gap:8px;font-size:10px;color:#53647a;margin-top:3px}.checkrow input{accent-color:var(--blue)}.calc-result{border:1px solid #dce7f4;background:#f7fbff;border-radius:10px;padding:16px;min-height:190px}.calc-result h3{font-size:12px;margin:0 0 10px}.calc-row{display:flex;justify-content:space-between;gap:14px;padding:8px 0;border-bottom:1px solid #e5edf6;font-size:10px;color:#69798d}.calc-row strong{color:#34475f}.calc-row.total{font-weight:850;color:#293f58}.calc-row.total strong{color:#216dc8;font-size:12px}.calc-result small{display:block;color:#8a97a7;font-size:9px;line-height:1.45;margin-top:11px}.modal-backdrop{position:fixed;inset:0;background:#15264088;display:none;align-items:center;justify-content:center;padding:18px;z-index:20}.modal-backdrop.open{display:flex}.modal{width:min(620px,100%);max-height:92vh;overflow:auto;background:#fff;border-radius:13px;box-shadow:var(--shadow)}.modal-head{display:flex;justify-content:space-between;gap:12px;padding:17px 18px;border-bottom:1px solid var(--line)}.modal-head h2{font-size:15px;margin:0}.modal-head p{font-size:10px;color:var(--muted);margin:5px 0 0}.close{border:0;background:#f1f4f8;width:30px;height:30px;border-radius:7px;font-size:18px;color:#5f6f82;cursor:pointer}.modal-body{padding:17px 18px}.modal-foot{border-top:1px solid var(--line);padding:13px 18px;display:flex;justify-content:flex-end;gap:8px}.rate-pick{display:grid;gap:7px;max-height:150px;overflow:auto;border:1px solid var(--line);border-radius:8px;padding:10px}.rate-pick label{display:flex;gap:8px;align-items:center;font-size:10px;color:#52647a}.rate-pick input{accent-color:var(--blue)}.loading{padding:25px;text-align:center;color:#8492a3;font-size:11px}@media(max-width:800px){.topbar{padding:0 14px;gap:12px}.biz,.user{display:none}.wrap{padding:20px 14px 35px}.head{display:block}.head .actions{margin-top:13px}.calc-grid{grid-template-columns:1fr}}@media(max-width:560px){.topnav a{font-size:10px;padding:8px}.brand{font-size:14px}.fields{grid-template-columns:1fr}.body{padding:11px}.tabs{padding:8px}.tab{padding:9px}.head h1{font-size:22px}}
    </style>
</head>
<body data-can-manage="{{ $canManage ? '1' : '0' }}" data-login-url="{{ route('login') }}">
<header class="topbar">
    <div class="brand">Press<span>Flow</span></div>
    <nav class="topnav"><a href="{{ route('dashboard') }}">Dashboard</a><a href="{{ route('taxes.index') }}" class="active">Tax Rates &amp; Groups</a>@if($canManageSettings)<a href="{{ route('settings.index') }}">Settings</a>@endif</nav>
    <div class="biz">{{ $workspace->name }}</div>
    <div class="user">{{ $user->name }}</div>
    <form method="POST" action="{{ route('logout') }}">@csrf<button class="logout" type="submit">Sign out</button></form>
</header>
<main class="wrap">
    <div class="eyebrow">Business configuration · Tax</div>
    <div class="head">
        <div><h1>Tax Rates &amp; Groups</h1><p>Set up reusable tax rates, combine them into groups, and choose whether the prices you enter include tax. Rates apply only to this business.</p></div>
        <div class="actions" id="manageActions" hidden><button class="btn" data-action="new-rate">＋ New tax rate</button><button class="btn primary" data-action="new-group">＋ New tax group</button></div>
    </div>
    <div class="notice"><strong>Tax configuration is intentionally separate.</strong> No official rate is preselected. Confirm your business's registration, applicable rates and inclusive/exclusive policy with your accountant before using tax on a final invoice. Final transactions must save a tax snapshot so later rate changes cannot alter history.</div>
    <div id="alert" class="alert"></div>
    <section class="card">
        <div class="tabs"><button class="tab active" data-tab="rates">Tax Rates</button><button class="tab" data-tab="groups">Tax Groups</button><button class="tab" data-tab="calculator">Tax Calculator</button></div>
        <div class="body" id="pageBody"><div class="loading">Loading tax setup…</div></div>
    </section>
</main>
<div class="modal-backdrop" id="modalBackdrop"><div class="modal" id="modal" role="dialog" aria-modal="true"></div></div>
<script>
const canManage=document.body.dataset.canManage==='1';
let activeTab='rates',taxRates=[],taxGroups=[];
const csrf=document.querySelector('meta[name="csrf-token"]').content;
const escapeHtml=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const rateText=rate=>Number(rate).toFixed(4).replace(/0+$/,'').replace(/\.$/,'');
const money=value=>'LKR '+Number(value||0).toLocaleString('en-LK',{minimumFractionDigits:2,maximumFractionDigits:2});
function showAlert(message,type='success'){const el=document.getElementById('alert');el.textContent=message;el.className='alert show '+(type==='error'?'error':'success');clearTimeout(showAlert.timer);showAlert.timer=setTimeout(()=>el.classList.remove('show'),4500)}
async function api(path,options={}){const method=options.method||'GET',headers={'Accept':'application/json',...(options.headers||{})};if(options.body){headers['Content-Type']='application/json';headers['X-CSRF-TOKEN']=csrf}const response=await fetch('/api/v1'+path,{method,credentials:'same-origin',headers,body:options.body?JSON.stringify(options.body):undefined});const data=await response.json().catch(()=>({}));if(response.status===401){window.location.href=document.body.dataset.loginUrl;throw new Error('Please sign in again.')}if(!response.ok){const firstError=data.errors?Object.values(data.errors).flat()[0]:null;throw new Error(firstError||data.message||'The request could not be completed.')}return data}
function listData(payload){return Array.isArray(payload.data)?payload.data:[]}
async function loadData(){document.getElementById('pageBody').innerHTML='<div class="loading">Loading tax setup…</div>';try{const [rates,groups]=await Promise.all([api('/tax/rates?per_page=100'),api('/tax/groups?per_page=100')]);taxRates=listData(rates);taxGroups=listData(groups);renderPage()}catch(error){document.getElementById('pageBody').innerHTML='<div class="empty">Tax setup could not be loaded. Check your access and connection.</div>';showAlert(error.message,'error')}}
function renderPage(){document.querySelectorAll('[data-tab]').forEach(button=>button.classList.toggle('active',button.dataset.tab===activeTab));if(activeTab==='rates')renderRates();else if(activeTab==='groups')renderGroups();else renderCalculator()}
function renderRates(){const rows=taxRates.map(rate=>`<tr><td><span class="code">${escapeHtml(rate.code)}</span></td><td><strong>${escapeHtml(rate.name)}</strong><div class="muted">${escapeHtml(rate.description||'')}</div></td><td>${rate.calculation_type==='percentage'?'Percentage':'Fixed / unit'}</td><td><strong>${rate.calculation_type==='percentage'?rateText(rate.rate)+'%':money(rate.rate)}</strong>${rate.is_compound?'<div class="muted">Compound</div>':''}</td><td>${escapeHtml(rate.valid_from||'—')}</td><td>${escapeHtml(rate.valid_until||'No end date')}</td><td>${Number(rate.groups_count||0)}</td><td><span class="status ${rate.is_active?'':'off'}">${rate.is_active?'Active':'Inactive'}</span></td><td>${canManage?`<div class="tools"><button class="btn small" data-edit-rate="${rate.id}">Edit</button><button class="btn small ${rate.is_active?'danger':''}" data-toggle-rate="${rate.id}">${rate.is_active?'Deactivate':'Activate'}</button></div>`:'<span class="muted">View only</span>'}</td></tr>`).join('');document.getElementById('pageBody').innerHTML=`<div class="subhead"><div><h2>Tax rates</h2><p>Rates can be percentage-based or fixed per quantity and can have effective dates.</p></div>${canManage?'<button class="btn primary" data-action="new-rate">＋ Add rate</button>':''}</div>${rows?`<div class="table-wrap"><table><thead><tr><th>Code</th><th>Rate name</th><th>Type</th><th>Rate</th><th>Valid from</th><th>Valid until</th><th>Groups</th><th>Status</th><th>Actions</th></tr></thead><tbody>${rows}</tbody></table></div>`:'<div class="empty">No tax rates yet. Add a rate after confirming the applicable business tax rules.</div>'}`}
function renderGroups(){const rows=taxGroups.map(group=>{const rates=Array.isArray(group.rates)?group.rates:[];return `<tr><td><span class="code">${escapeHtml(group.code)}</span></td><td><strong>${escapeHtml(group.name)}</strong><div class="muted">${escapeHtml(group.description||'')}</div></td><td><div class="rate-stack">${rates.map(rate=>`<span class="rate-chip">${escapeHtml(rate.name)} · ${rate.calculation_type==='percentage'?rateText(rate.rate)+'%':money(rate.rate)}</span>`).join('')||'<span class="muted">No rates</span>'}</div></td><td>${group.is_inclusive?'Tax-inclusive':'Tax-exclusive'}</td><td><span class="status ${group.is_active?'':'off'}">${group.is_active?'Active':'Inactive'}</span></td><td>${canManage?`<div class="tools"><button class="btn small" data-edit-group="${group.id}">Edit</button><button class="btn small ${group.is_active?'danger':''}" data-toggle-group="${group.id}">${group.is_active?'Deactivate':'Activate'}</button></div>`:'<span class="muted">View only</span>'}</td></tr>`}).join('');document.getElementById('pageBody').innerHTML=`<div class="subhead"><div><h2>Tax groups</h2><p>Combine active rates and define how prices are entered.</p></div>${canManage?'<button class="btn primary" data-action="new-group">＋ Add group</button>':''}</div>${rows?`<div class="table-wrap"><table><thead><tr><th>Code</th><th>Group</th><th>Included rates</th><th>Price mode</th><th>Status</th><th>Actions</th></tr></thead><tbody>${rows}</tbody></table></div>`:'<div class="empty">No tax groups yet. Create a rate first, then assemble the rate or rates into a group.</div>'}`}
function renderCalculator(){const groups=taxGroups.filter(group=>group.is_active);document.getElementById('pageBody').innerHTML=`<div class="calc-grid"><div class="calc-box"><h2>Tax calculator</h2><p>Preview the tax treatment of one line amount. The finalized sale or purchase must be recalculated by Laravel and persist its rate snapshot.</p><div class="fields"><div class="field"><label for="calcGroup">Tax group</label><select class="select" id="calcGroup">${groups.map(group=>`<option value="${group.id}">${escapeHtml(group.name)} · ${group.is_inclusive?'inclusive':'exclusive'}</option>`).join('')}</select></div><div class="field"><label for="calcAmount">Entered amount (LKR)</label><input class="input" id="calcAmount" type="number" min="0" step="0.01" value="10000"></div><div class="field"><label for="calcQuantity">Quantity (fixed rates)</label><input class="input" id="calcQuantity" type="number" min="0.0001" step="0.01" value="1"></div></div><div style="margin-top:13px"><button class="btn primary" data-action="calculate">Calculate tax</button></div></div><div class="calc-result" id="calcResult"><h3>Preview result</h3><p class="muted">Choose an active tax group and calculate to view the amount breakdown.</p></div></div>`;if(!groups.length)document.getElementById('calcGroup').innerHTML='<option value="">No active tax groups</option>'}
function openModal(html){document.getElementById('modal').innerHTML=html;document.getElementById('modalBackdrop').classList.add('open');document.body.style.overflow='hidden';document.querySelector('#modal input')?.focus()}
function closeModal(){document.getElementById('modalBackdrop').classList.remove('open');document.body.style.overflow='';document.getElementById('modal').innerHTML=''}
function rateModal(rate=null){const editing=!!rate;openModal(`<div class="modal-head"><div><h2>${editing?'Edit tax rate':'New tax rate'}</h2><p>Keep rate codes stable; finalized documents retain a separate tax snapshot.</p></div><button class="close" type="button" data-close>×</button></div><form id="rateForm" data-id="${rate?.id||''}"><div class="modal-body"><div class="fields"><div class="field"><label>Tax name *</label><input class="input" name="name" required maxlength="120" value="${escapeHtml(rate?.name||'')}"></div><div class="field"><label>Code *</label><input class="input" name="code" required maxlength="40" value="${escapeHtml(rate?.code||'')}"></div><div class="field"><label>Calculation type</label><select class="select" name="calculation_type"><option value="percentage" ${rate?.calculation_type==='percentage'?'selected':''}>Percentage</option><option value="fixed" ${rate?.calculation_type==='fixed'?'selected':''}>Fixed amount per unit</option></select></div><div class="field"><label>Rate *</label><input class="input" name="rate" type="number" min="0" step="0.0001" required value="${escapeHtml(rate?.rate??'')}"></div><div class="field"><label>Valid from</label><input class="input" name="valid_from" type="date" value="${escapeHtml(rate?.valid_from||'')}"></div><div class="field"><label>Valid until</label><input class="input" name="valid_until" type="date" value="${escapeHtml(rate?.valid_until||'')}"></div><div class="field" style="grid-column:1/-1"><label>Description</label><input class="input" name="description" maxlength="2000" value="${escapeHtml(rate?.description||'')}"></div><div class="checkrow" style="grid-column:1/-1"><input type="checkbox" name="is_compound" ${rate?.is_compound?'checked':''}><label>Compound: apply this rate after the preceding tax components</label></div><div class="checkrow" style="grid-column:1/-1"><input type="checkbox" name="is_active" ${rate?.is_active===false?'':'checked'}><label>Rate is active</label></div></div></div><div class="modal-foot"><button class="btn" type="button" data-close>Cancel</button><button class="btn primary">${editing?'Save changes':'Save tax rate'}</button></div></form>`)}
function groupModal(group=null){const editing=!!group,selected=new Set((group?.rates||[]).map(rate=>String(rate.id)));openModal(`<div class="modal-head"><div><h2>${editing?'Edit tax group':'New tax group'}</h2><p>Choose active rates and a price-inclusion policy.</p></div><button class="close" type="button" data-close>×</button></div><form id="groupForm" data-id="${group?.id||''}"><div class="modal-body"><div class="fields"><div class="field"><label>Group name *</label><input class="input" name="name" required maxlength="120" value="${escapeHtml(group?.name||'')}"></div><div class="field"><label>Code *</label><input class="input" name="code" required maxlength="40" value="${escapeHtml(group?.code||'')}"></div><div class="field" style="grid-column:1/-1"><label>Tax rates *</label><div class="rate-pick">${taxRates.filter(rate=>rate.is_active||selected.has(String(rate.id))).map(rate=>`<label><input type="checkbox" name="tax_rate_ids" value="${rate.id}" ${selected.has(String(rate.id))?'checked':''}> ${escapeHtml(rate.name)} · ${rate.calculation_type==='percentage'?rateText(rate.rate)+'%':money(rate.rate)}${rate.is_active?'':' (inactive)'}</label>`).join('')||'<span class="muted">Create and activate a tax rate first.</span>'}</div></div><div class="checkrow" style="grid-column:1/-1"><input type="checkbox" name="is_inclusive" ${group?.is_inclusive?'checked':''}><label>Prices entered for this group already include tax</label></div><div class="field" style="grid-column:1/-1"><label>Description</label><input class="input" name="description" maxlength="2000" value="${escapeHtml(group?.description||'')}"></div><div class="checkrow" style="grid-column:1/-1"><input type="checkbox" name="is_active" ${group?.is_active===false?'':'checked'}><label>Tax group is active</label></div></div></div><div class="modal-foot"><button class="btn" type="button" data-close>Cancel</button><button class="btn primary">${editing?'Save changes':'Save tax group'}</button></div></form>`)}
function renderCalculation(result){const rows=(result.rates||[]).map(rate=>`<div class="calc-row"><span>${escapeHtml(rate.name)} ${rate.calculation_type==='percentage'?`(${rateText(rate.rate)}%)`: '(fixed)'}</span><strong>${money(rate.amount)}</strong></div>`).join('');document.getElementById('calcResult').innerHTML=`<h3>Calculated amount</h3><div class="calc-row"><span>Taxable amount</span><strong>${money(result.taxable_amount)}</strong></div>${rows}<div class="calc-row total"><span>Tax total</span><strong>${money(result.tax_amount)}</strong></div><div class="calc-row total"><span>Invoice total</span><strong>${money(result.total)}</strong></div><small>Preview only. Final documents are recalculated and snapshotted by Laravel.</small>`}

document.addEventListener('click',async event=>{const tab=event.target.closest('[data-tab]');if(tab){activeTab=tab.dataset.tab;renderPage();return}if(event.target.closest('[data-close]')){closeModal();return}if(event.target.id==='modalBackdrop'){closeModal();return}const action=event.target.closest('[data-action]')?.dataset.action;if(action==='new-rate'){rateModal();return}if(action==='new-group'){groupModal();return}if(action==='calculate'){const groupId=document.getElementById('calcGroup')?.value;try{const result=await api('/tax/preview',{method:'POST',body:{tax_group_id:Number(groupId),amount:Number(document.getElementById('calcAmount').value),quantity:Number(document.getElementById('calcQuantity').value||1)}});renderCalculation(result)}catch(error){showAlert(error.message,'error')}return}const editRate=event.target.closest('[data-edit-rate]');if(editRate){rateModal(taxRates.find(rate=>String(rate.id)===editRate.dataset.editRate));return}const editGroup=event.target.closest('[data-edit-group]');if(editGroup){groupModal(taxGroups.find(group=>String(group.id)===editGroup.dataset.editGroup));return}const toggleRate=event.target.closest('[data-toggle-rate]');if(toggleRate){const rate=taxRates.find(item=>String(item.id)===toggleRate.dataset.toggleRate);if(!rate)return;try{await api(`/tax/rates/${rate.id}`,{method:'PATCH',body:{is_active:!rate.is_active}});showAlert('Tax rate status updated.');await loadData()}catch(error){showAlert(error.message,'error')}return}const toggleGroup=event.target.closest('[data-toggle-group]');if(toggleGroup){const group=taxGroups.find(item=>String(item.id)===toggleGroup.dataset.toggleGroup);if(!group)return;try{await api(`/tax/groups/${group.id}`,{method:'PATCH',body:{is_active:!group.is_active}});showAlert('Tax group status updated.');await loadData()}catch(error){showAlert(error.message,'error')}}});
document.addEventListener('submit',async event=>{if(event.target.id!=='rateForm'&&event.target.id!=='groupForm')return;event.preventDefault();const form=event.target,fd=new FormData(form),id=form.dataset.id||null,isRate=form.id==='rateForm';let body={name:String(fd.get('name')||'').trim(),code:String(fd.get('code')||'').trim().toUpperCase(),description:String(fd.get('description')||'').trim()||null,is_active:fd.has('is_active')};let path,method;if(isRate){body={...body,calculation_type:String(fd.get('calculation_type')),rate:Number(fd.get('rate')),is_compound:fd.has('is_compound'),valid_from:fd.get('valid_from')||null,valid_until:fd.get('valid_until')||null};path=id?`/tax/rates/${id}`:'/tax/rates';method=id?'PATCH':'POST'}else{body={...body,is_inclusive:fd.has('is_inclusive'),tax_rate_ids:fd.getAll('tax_rate_ids').map(Number)};path=id?`/tax/groups/${id}`:'/tax/groups';method=id?'PATCH':'POST'}try{await api(path,{method,body});closeModal();showAlert(isRate?'Tax rate saved.':'Tax group saved.');await loadData()}catch(error){showAlert(error.message,'error')}});
document.addEventListener('keydown',event=>{if(event.key==='Escape')closeModal()});
if(!canManage)document.getElementById('manageActions').hidden=true;
loadData();
